package com.adib.maintenance;
import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w360dp-h800dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class HomeScreenVisualTest {
 void set(MainActivity a,String n,Object v)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);f.set(a,v);}JSONObject task(String id,String title,String parent,String container,int n)throws Exception{return new JSONObject().put("id",id).put("title",title).put("parentId",parent).put("containerId",container).put("pomodoroCount",n).put("pomodoroMinutes",n*25);}
 void shot(boolean dark,int width,float scale)throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"dark",dark);android.content.res.Configuration cfg=a.getResources().getConfiguration();cfg.fontScale=scale;a.getResources().updateConfiguration(cfg,a.getResources().getDisplayMetrics());a.getResources().getDisplayMetrics().scaledDensity=scale;JSONArray tasks=new JSONArray().put(task("p","Tablet yağlama alarmı","","inbox",2)).put(task("c","Sensoru yoxla","p","",1)).put(task("r","Materialları sifariş et","","day",0)).put(task("s","Pompa səsini yoxlamaq","","inbox",0));set(a,"personalTasks",tasks);set(a,"personalPomodoroTasks",tasks);set(a,"personalContainers",new JSONArray().put(new JSONObject().put("id","inbox").put("name","INBOX")).put(new JSONObject().put("id","day").put("name","My Day")).put(new JSONObject().put("id","later").put("name","Sonra")));set(a,"refreshStatus","Yenilənib 12:42");Method m=MainActivity.class.getDeclaredMethod("render");m.setAccessible(true);m.invoke(a);Field f=MainActivity.class.getDeclaredField("root");f.setAccessible(true);View root=(View)f.get(a);root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY));root.layout(0,0,width,800);View nav=root.findViewWithTag("home-navigation"),search=root.findViewWithTag("home-search"),body=root.findViewWithTag("home-task:p");assertTrue(nav.getBottom()<=800);assertEquals(View.GONE,search.getVisibility());assertTrue(body.getHeight()>40);assertTrue(nav.getTop()>search.getBottom());for(int i:new int[]{0,5,4,2}){View b=root.findViewWithTag("home-nav:"+i);assertTrue(b.getHeight()>=48);assertTrue(b.getRight()<=((View)b.getParent()).getWidth());System.out.println("NAV_LAYOUT "+i+" "+((TextView)b).getText()+" height="+b.getHeight()+" top="+b.getTop()+" text="+((TextView)b).getTextSize()+" pad="+((TextView)b).getExtendedPaddingTop()+" baseline="+((TextView)b).getBaseline()+" color="+((TextView)b).getCurrentTextColor());assertNotNull(((TextView)b).getLayout());assertEquals(((TextView)b).getText().length(),((TextView)b).getLayout().getLineEnd(0));}Bitmap bitmap=Bitmap.createBitmap(width,800,Bitmap.Config.ARGB_8888);root.draw(new Canvas(bitmap));int bluePixels=0;for(int y=nav.getTop();y<Math.min(800,nav.getBottom());y++)for(int x=0;x<width;x++)if((bitmap.getPixel(x,y)&0xffffff)==(HybridUi.accent(dark)&0xffffff))bluePixels++;assertTrue("Navigation labels visibly drawn",bluePixels>0);File dir=new File("/data/adib-work/qa/compact-native-previews");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"home-android-"+(dark?"dark":"light")+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}a.onDestroy();}
 @Test public void light360()throws Exception{shot(false,360,1);}@Test public void darkLargeText320()throws Exception{shot(true,320,1.4f);}
}
